/* CreativeHub — Shared Styles */
:root {
  --red: #F02D00;
  --dark: #171717;
  --white: #FFFFFF;
  --gray-50: #f9f9f9;
  --gray-100: #f2f2f2;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-700: #404040;
  --gray-800: #262626;
  --teal: #00B89F;
  --green: #22C55E;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 2px 12px rgba(0,0,0,0.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.14);
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ---- Promo Banner ---- */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 10px 20px;
  font-size: 0.875rem;
  position: relative;
}
.promo-banner strong { color: var(--red); }
.promo-banner .countdown { display: inline-flex; gap: 4px; font-weight: 700; font-size: 1rem; }
.promo-banner .countdown span {
  background: var(--red);
  color: var(--white);
  border-radius: 4px;
  padding: 2px 6px;
  min-width: 32px;
  text-align: center;
}
.promo-banner .dismiss {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 1.25rem; line-height: 1;
  background: none; border: none; cursor: pointer;
  transition: color var(--transition);
}
.promo-banner .dismiss:hover { color: var(--white); }

/* ---- Header / Nav ---- */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.logo {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
  white-space: nowrap;
}
.logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: background var(--transition), color var(--transition);
}
.nav-links a:hover, .nav-links a.active { background: var(--gray-100); color: var(--dark); }
.nav-links a.plus-link { color: var(--red); font-weight: 700; }
.search-bar {
  flex: 1;
  max-width: 380px;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 9px 16px 9px 40px;
  border: 1.5px solid var(--gray-200);
  border-radius: 24px;
  font-size: 0.875rem;
  background: var(--gray-50);
  color: var(--dark);
  outline: none;
  transition: border-color var(--transition);
}
.search-bar input:focus { border-color: var(--dark); background: var(--white); }
.search-bar .search-icon {
  position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); pointer-events: none;
}
.nav-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 20px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-outline {
  border: 1.5px solid var(--dark);
  color: var(--dark);
  background: transparent;
}
.btn-outline:hover { background: var(--dark); color: var(--white); }
.btn-primary {
  background: var(--dark);
  color: var(--white);
  border: 1.5px solid var(--dark);
}
.btn-primary:hover { background: var(--gray-800); }
.btn-red {
  background: var(--red);
  color: var(--white);
  border: 1.5px solid var(--red);
}
.btn-red:hover { background: #d12600; border-color: #d12600; }
.btn-lg { padding: 13px 28px; font-size: 1rem; border-radius: 10px; }

/* ---- Container ---- */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ---- Section Titles ---- */
.section-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.section-subtitle {
  font-size: 1rem;
  color: var(--gray-500);
  margin-bottom: 28px;
}

/* ---- Course Card ---- */
.course-card {
  background: var(--white);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}
.course-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }
.course-card-img {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: linear-gradient(135deg, var(--gray-200) 0%, var(--gray-300) 100%);
  position: relative;
}
.course-card-img-placeholder {
  width: 100%;
  aspect-ratio: 16/10;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.course-card-body { padding: 14px 16px; flex: 1; display: flex; flex-direction: column; gap: 6px; }
.course-card-title { font-size: 0.9375rem; font-weight: 700; color: var(--dark); line-height: 1.3; }
.course-card-instructor { font-size: 0.8125rem; color: var(--gray-500); }
.course-card-meta { display: flex; align-items: center; gap: 8px; font-size: 0.8125rem; flex-wrap: wrap; }
.badge-bestseller {
  background: #fef3c7;
  color: #92400e;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.badge-new {
  background: #dcfce7;
  color: #166534;
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
}
.badge-free {
  background: var(--teal);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
}
.rating { color: var(--dark); font-weight: 600; }
.price { font-weight: 800; color: var(--dark); font-size: 1rem; }
.price-original { text-decoration: line-through; color: var(--gray-400); font-size: 0.8125rem; }
.discount-badge {
  background: var(--red);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 4px;
}
.students-count { color: var(--gray-500); }

/* ---- Carousel ---- */
.carousel-wrap { position: relative; }
.carousel-track {
  display: flex;
  gap: 20px;
  overflow: hidden;
}
.carousel-track.dragging { cursor: grabbing; user-select: none; }
.carousel-btn {
  position: absolute;
  top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px;
  border-radius: 50%;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  box-shadow: var(--shadow);
  display: flex; align-items: center; justify-content: center;
  z-index: 10;
  transition: all var(--transition);
  font-size: 1.125rem;
}
.carousel-btn:hover { background: var(--dark); color: var(--white); border-color: var(--dark); }
.carousel-btn.prev { left: -22px; }
.carousel-btn.next { right: -22px; }
.carousel-btn:disabled { opacity: 0.3; cursor: default; }

/* ---- Dots ---- */
.carousel-dots {
  display: flex; justify-content: center; gap: 8px; margin-top: 20px;
}
.carousel-dots button {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300); transition: all var(--transition);
  padding: 0; border: none;
}
.carousel-dots button.active { background: var(--dark); width: 24px; border-radius: 4px; }

/* ---- Footer ---- */
.site-footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: 56px 0 32px;
  margin-top: 80px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 32px 24px;
  margin-bottom: 48px;
}
.footer-col h4 {
  color: var(--white);
  font-size: 0.8125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 14px;
}
.footer-col a {
  display: block;
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 8px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
}
.footer-logo { color: var(--white); font-weight: 800; font-size: 1.125rem; }
.footer-logo span { color: var(--red); }
.footer-legal { display: flex; gap: 16px; flex-wrap: wrap; }
.footer-legal a { color: var(--gray-500); font-size: 0.8125rem; }
.footer-legal a:hover { color: var(--gray-300); }

/* ---- Color placeholder gradients ---- */
.grad-1 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
.grad-2 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
.grad-3 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
.grad-4 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }
.grad-5 { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); }
.grad-6 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
.grad-7 { background: linear-gradient(135deg, #ffecd2 0%, #fcb69f 100%); }
.grad-8 { background: linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%); }
.grad-9 { background: linear-gradient(135deg, #a1c4fd 0%, #c2e9fb 100%); }
.grad-10 { background: linear-gradient(135deg, #d4fc79 0%, #96e6a1 100%); }

/* ---- Value Props Grid ---- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}
.value-card {
  padding: 24px;
  background: var(--gray-50);
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
}
.value-card .icon { font-size: 1.75rem; margin-bottom: 12px; }
.value-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 6px; }
.value-card p { font-size: 0.875rem; color: var(--gray-500); line-height: 1.6; }

/* ---- Responsive ---- */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .search-bar { max-width: 100%; }
  .section-title { font-size: 1.375rem; }
  .carousel-btn.prev { left: -8px; }
  .carousel-btn.next { right: -8px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .header-inner { gap: 16px; }
}

