/* CreativeHub — Shared Styles */
:root {
  --red: #F02D00;
  --dark: #171717;
  --white: #FFFFFF;
  --gray-50: #f9f9f9;
  --gray-100: #f2f2f2;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-700: #404040;
  --gray-800: #262626;
  --teal: #00B89F;
  --green: #22C55E;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 2px 12px rgba(0,0,0,0.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.14);
  --transition: 0.2s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
img { display: block; max-width: 100%; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

/* ---- Promo Banner ---- */
.promo-banner {
  background: var(--dark);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 10px 20px;
  font-size: 0.875rem;
  position: relative;
}
.promo-banner strong { color: var(--red); }
.promo-banner .countdown { display: inline-flex; gap: 4px; font-weight: 700; font-size: 1rem; }
.promo-banner .countdown span {
  background: var(--red);
  color: var(--white);
  border-radius: 4px;
  padding: 2px 6px;
  min-width: 32px;
  text-align: center;
}
.promo-banner .dismiss {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); font-size: 1.25rem; line-height: 1;
  background: none; border: none; cursor: pointer;
  transition: color var(--transition);
}
.promo-banner .dismiss:hover { color: var(--white); }

/* ---- Header / Nav ---- */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.logo {
  font-size: 1.375rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
  white-space: nowrap;
}
.logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: background var(--transition), color var(--transition);
}
.nav-links a:hover, .nav-links a.active { background: var(--gray-100); color: var(--dark); }
.nav-links a.plus-link { color: var(--red); font-weight: 700; }
.search-bar {
  flex: 1;
  max-width: 380px;
  position: relative;
}
.search-bar input {
  width: 100%;
  padding: 9px 16px 9px 40px;
  border: 1.5px solid var(--gray-200);
  border-radius: 24px;
  font-size: 0.875rem;
  background: var(--gray-50);
  color: var(--dark);
  outline: none;
  transition: border-color var(--transition);
}
.search-bar input:focus { border-color: var(--dark); background: var(--white); }
.search-bar .search-icon {
  position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
  color: var(--gray-400); pointer-events: none;
}
.nav-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 20px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-outline {
  border: 1.5px solid var(--dark);
  color: var(--dark);
  background: transparent;
}
.btn-outline:hover { background: var(--dark); color: var(--white); }
.btn-primary {
  background: var(--dark);
  color: var(--white);
  border: 1.5px solid var(--dark);
}
.btn-primary:hover { background: var(--gray-800); }
.btn-red {
  background: var(--red);
  color: var(--white);
  border: 1.5px solid var(--red);
}
.btn-red:hover { background: #d12600; border-color: #d12600; }
.btn-lg { padding: 13px 28px; font-size: 1rem; border-radius: 10px; }

/* ---- Container ---- */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ---- Section Titles ---- */
.section-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}
.section-subtitle {
  font-size: 1rem;
  color: var(--gray-500);
  margin-bottom: 28px;
}

/* ---- Course Card ---- */
.course-card {
  background: var(--white);
  border-radius: var(--radius);
