  color: var(--gray-400);
  font-size: 0.8125rem;
  font-weight: 500;
}
.form-divider::before, .form-divider::after {
  content: ''; flex: 1; height: 1px; background: var(--gray-200);
}

/* Form Fields */
.form-group { margin-bottom: 16px; }
.form-label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 6px;
}
.form-input {
  width: 100%;
  padding: 12px 16px;
